def transform(grid):
    h, w = len(grid), len(grid[0])

    # Each row is a one-cell shift of the previous row: colors therefore
    # follow diagonals of constant r+c. Infer the repeating diagonal period
    # from the nonzero observations.
    obs = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                obs[r + c] = grid[r][c]

    period = None
    for p in range(1, h + w):
        if all(obs[a] == obs[b]
               for a in obs for b in obs
               if (a - b) % p == 0):
            period = p
            break

    vals = {}
    for s, v in obs.items():
        vals[s % period] = v

    # Fill unobserved residue classes by extending the observed color cycle.
    known = sorted(vals)
    for k in range(period):
        if k not in vals:
            prev = max((x for x in known if x < k), default=known[-1])
            vals[k] = vals[prev]

    return [[vals[(r + c) % period] for c in range(w)] for r in range(h)]
